  await t.test('corrections preserve raw history, require manager approval and reject inspected or stale entries',async()=>{
   const x=await seed('CORRECTION',{assignedUser:other});
   assert.equal((await call('POST',x.prod+'/start',{},'cor-start',ot)).statusCode,200);
   const recorded=await call('POST',x.prod+'/results',{lotId:x.lot,kind:'pending',quantity:6,separateQualityRequest:true},'cor-record',ot);
   assert.equal(recorded.statusCode,201,recorded.body);const eventId=recorded.json().eventId;
   const body={eventId,quantity:2,reason:'Entered six instead of two'};
   let r=await call('POST',x.prod+'/corrections',body,'cor-request',ot);assert.equal(r.statusCode,201,r.body);const requestId=r.json().id;
   assert.equal((await call('POST',x.prod+'/corrections',body,'cor-request',ot)).json().id,requestId);
   assert.equal((await call('POST',x.prod+'/corrections',body,'cor-duplicate',ot)).statusCode,409);
   assert.equal((await call('GET',x.prod+'/balances')).json().consumedQuantity,6);
   const decision={requestId,approved:true,reason:'Count verified at machine'};
   assert.equal((await call('POST',x.prod+'/correction-decision',decision,'cor-denied',ot)).statusCode,403);
   r=await call('POST',x.prod+'/correction-decision',decision,'cor-approve');assert.equal(r.statusCode,200,r.body);
   assert.equal((await call('POST',x.prod+'/correction-decision',decision,'cor-approve')).statusCode,200);
   assert.equal((await call('POST',x.prod+'/correction-decision',decision,'cor-second')).statusCode,409);
   const balance=(await call('GET',x.prod+'/balances')).json();assert.equal(balance.consumedQuantity,2);assert.equal(balance.remainingUsableInput,8);
   assert.equal((await call('GET',x.root+`/work-orders/${x.j}/quality`)).json().outputs[0].produced,2);
   const raw=await admin.query(`SELECT quantity_pieces FROM "${schema}".production_events WHERE id=$1`,[eventId]);assert.equal(Number(raw.rows[0].quantity_pieces),6);
   const hist=(await call('GET',x.prod+'/history')).json();assert.equal(hist.events[0].quantity,2);assert.equal(hist.corrections[0].originalQuantity,6);assert.equal(hist.corrections[0].status,'approved');
   assert.equal((await call('POST',x.prod+'/corrections',{...body,quantity:1},'cor-again',ot)).statusCode,409);
   const second=await call('POST',x.prod+'/results',{lotId:x.lot,kind:'pending',quantity:3,separateQualityRequest:true},'cor-next',ot);
   const secondId=second.json().eventId;
   const pending=await call('POST',x.prod+'/corrections',{eventId:secondId,quantity:0,reason:'Duplicate entry'},'cor-zero',ot);assert.equal(pending.statusCode,201,pending.body);
   assert.equal((await call('POST',x.prod+'/request-quality',{eventIds:[secondId]},'cor-quality',ot)).statusCode,201);
   const stale={requestId:pending.json().id,approved:true,reason:'Approve correction'};
   assert.equal((await call('POST',x.prod+'/correction-decision',stale,'cor-stale')).statusCode,409);
   assert.equal((await call('POST',x.prod+'/correction-decision',{...stale,approved:false,reason:'Already sent for inspection'},'cor-reject')).statusCode,200);
   const third=await call('POST',x.prod+'/results',{lotId:x.lot,kind:'pending',quantity:1,separateQualityRequest:true},'cor-third',ot);
   const zero=await call('POST',x.prod+'/corrections',{eventId:third.json().eventId,quantity:0,reason:'Duplicate entry'},'cor-void',ot);
   assert.equal((await call('POST',x.prod+'/correction-decision',{requestId:zero.json().id,approved:true,reason:'Duplicate confirmed'},'cor-void-approve')).statusCode,200);
   assert.equal((await call('GET',x.prod+'/balances')).json().consumedQuantity,5);
   assert.equal((await pool.query('SELECT * FROM production_correction_requests')).rowCount,0);
   await assert.rejects(pool.query('DELETE FROM production_correction_requests'),{code:'42501'});
   await admin.query(`UPDATE "${schema}".work_assignments SET released_at=now() WHERE work_order_id=$1`,[x.j]);
  });
  await t.test('five-minute own-entry edits, manager override, scrap, versioning and completion locks',async()=>{
   const x=await seed('QUICK-EDIT',{assignedUser:other});
   assert.equal((await call('POST',x.prod+'/start',{},'qe-start',ot)).statusCode,200);
   const record=await call('POST',x.prod+'/results',{lotId:x.lot,kind:'pending',quantity:6,separateQualityRequest:true},'qe-create',ot);assert.equal(record.statusCode,201,record.body);
   const eventId=record.json().eventId;
   let body={eventId,version:null,quantity:2,reason:'Correct counted quantity'};
   let r=await call('POST',x.prod+'/entry-corrections',body,'qe-edit',ot);assert.equal(r.statusCode,200,r.body);let version=r.json().id;
   assert.equal((await call('POST',x.prod+'/entry-corrections',body,'qe-edit',ot)).json().id,version);
   assert.equal((await call('GET',x.prod+'/balances')).json().consumedQuantity,2);
   assert.equal((await call('POST',x.prod+'/entry-corrections',{...body,quantity:3},'qe-stale',ot)).statusCode,409);
   r=await call('POST',x.prod+'/entry-corrections',{...body,version,quantity:8},'qe-increase',ot);assert.equal(r.statusCode,200,r.body);version=r.json().id;
   assert.equal((await call('POST',x.prod+'/entry-corrections',{...body,version,quantity:21},'qe-too-much',ot)).statusCode,409);
   r=await call('POST',x.prod+'/entry-corrections',{...body,version,quantity:0},'qe-zero',ot);assert.equal(r.statusCode,200,r.body);version=r.json().id;
   r=await call('POST',x.prod+'/entry-corrections',{...body,version,quantity:3},'qe-restore',ot);assert.equal(r.statusCode,200,r.body);
   assert.equal((await admin.query(`SELECT quantity_pieces FROM "${schema}".production_events WHERE id=$1`,[eventId])).rows[0].quantity_pieces,'6');
   let history=(await call('GET',x.prod+'/history',null,null,ot)).json();assert.equal(history.events.find(e=>e.eventId===eventId).edit.canEdit,true);assert.equal(history.corrections.filter(e=>e.status==='approved').length,4);
   const scrap=await call('POST',x.prod+'/results',{lotId:x.lot,kind:'scrap',quantity:2},'qe-scrap',ot);assert.equal(scrap.statusCode,201,scrap.body);
   r=await call('POST',x.prod+'/entry-corrections',{...body,eventId:scrap.json().eventId,quantity:1},'qe-scrap-edit',ot);assert.equal(r.statusCode,200,r.body);
   const raced=await call('POST',x.prod+'/results',{lotId:x.lot,kind:'pending',quantity:1,separateQualityRequest:true},'qe-race-record',ot);assert.equal(raced.statusCode,201,raced.body);
   const raceId=raced.json().eventId,raceBody={...body,eventId:raceId};
   const race=await Promise.all([call('POST',x.prod+'/entry-corrections',{...raceBody,quantity:2},'qe-race-a',ot),call('POST',x.prod+'/entry-corrections',{...raceBody,quantity:3},'qe-race-b',ot)]);assert.deepEqual(race.map(r=>r.statusCode).sort(),[200,409]);
   const accepted=race.find(r=>r.statusCode===200).json();
   assert.equal((await call('POST',x.prod+'/request-quality',{eventIds:[raceId]},'qe-request-quality',ot)).statusCode,201);
   assert.equal((await call('POST',x.prod+'/entry-corrections',{...raceBody,version:accepted.id,quantity:0},'qe-inspected',ot)).statusCode,409);
   // A backdated fixture is inserted, never updated: history is immutable.
   const old=id();await admin.query(`INSERT INTO "${schema}".production_events(tenant_id,site_id,id,work_order_id,kind,quantity_pieces,actor_id,occurred_at) VALUES($1,$2,$3,$4,'setup_scrap',2,$5,now()-interval '6 minutes')`,[ta,sa,old,x.j,other]);
   await admin.query(`INSERT INTO "${schema}".production_ledger(tenant_id,site_id,order_id,id,work_order_id,lot_id,production_event_id,kind,quantity_pieces,actor_id,event_kind) VALUES($1,$2,$3,$4,$5,$6,$7,'consume',2,$8,'setup_scrap'),($1,$2,$3,$9,$5,$6,$7,'setup_scrap',2,$8,'setup_scrap')`,[ta,sa,x.o,id(),x.j,x.lot,old,other,id()]);
   r=await call('POST',x.prod+'/entry-corrections',{...body,eventId:old,quantity:1},'qe-expired',ot);assert.equal(r.statusCode,409,r.body);
   r=await call('POST',x.prod+'/entry-corrections',{...body,eventId:old,quantity:1},'qe-admin');assert.equal(r.statusCode,200,r.body);
   history=(await call('GET',x.prod+'/history',null,null,ot)).json();assert.equal(history.events.find(e=>e.eventId===old).edit.canEdit,false);
   await admin.query(`UPDATE "${schema}".work_orders SET status='complete' WHERE id=$1`,[x.j]);
   r=await call('POST',x.prod+'/entry-corrections',{...body,version:r.json().id,eventId:old,quantity:0},'qe-finished',ot);assert.equal(r.statusCode,409,r.body);
   assert.equal((await call('GET',x.prod+'/history',null,null,ot)).json().events.every(e=>!e.edit.canEdit),true);
   await admin.query(`UPDATE "${schema}".work_assignments SET released_at=now() WHERE work_order_id=$1`,[x.j]);
   const otherJob=await seed('QE-OTHER');assert.equal((await call('POST',otherJob.prod+'/start',{},'qe-other-start')).statusCode,200);
   const otherRecord=await call('POST',otherJob.prod+'/results',{lotId:otherJob.lot,kind:'scrap',quantity:2},'qe-other-record');
   r=await call('POST',otherJob.prod+'/entry-corrections',{...body,eventId:otherRecord.json().eventId,quantity:1},'qe-other-denied',ot);assert.equal(r.statusCode,403,r.body);
   await admin.query(`UPDATE "${schema}".work_assignments SET released_at=now() WHERE work_order_id=$1`,[otherJob.j]);
  });
  await t.test('operator sees actual machine rank and persistent, self-only priority increases',async()=>{
   const x=await seed('PRIORITY',{assignedUser:other}),ahead=await seed('PRIORITY-AHEAD');
   await admin.query(`UPDATE "${schema}".work_orders SET queue_position=CASE WHEN id=$1 THEN 2048 ELSE 1024 END WHERE id IN ($1,$2)`,[x.j,ahead.j]);
   await admin.query(`UPDATE "${schema}".work_assignments SET machine_id=$1 WHERE work_order_id=$2`,[x.machineId,ahead.j]);
   const notifications=base+'/operator/notifications';
   let jobs=(await call('GET',base+'/operator/work-orders',null,null,ot)).json().workOrders;
   assert.equal(jobs.find(j=>j.id===x.j).queueRank,2);assert.equal(jobs.find(j=>j.id===x.j).priority,0);
   async function priority(value,key){const old=(await call('GET',x.root+'/editing')).json();const r=await call('POST',x.root+'/update',{version:old.version,orderedQuantity:x.amount,customerId:old.customerId,partId:old.partId,dueDate:old.dueDate,reference:old.reference,notes:old.notes,priority:value,reason:'Operator priority verification'},key);assert.equal(r.statusCode,200,r.body)}
   await priority(1,'priority-low');assert.equal((await call('GET',notifications,null,null,ot)).json().priorityChanges.length,0);
   await priority(2,'priority-high');let notices=(await call('GET',notifications,null,null,ot)).json();assert.equal(notices.priorityChanges.length,1);let n=notices.priorityChanges[0];assert.equal(n.priority,2);assert.equal(n.previous_priority,1);assert.equal(n.work_order_id,x.j);
   assert.equal((await call('GET',notifications)).json().priorityChanges.length,0);
   const acknowledge=notifications+'/'+n.id+'/priority/acknowledge';
   assert.equal((await call('POST',acknowledge,{eventId:n.event_id},'priority-forbidden')).statusCode,403);
   assert.equal((await call('GET',notifications,null,null,ot)).json().priorityChanges.length,1,'Unread notice persists over repeat requests');
   assert.equal((await call('POST',acknowledge,{eventId:n.event_id},'priority-seen',ot)).statusCode,200);
   assert.equal((await call('GET',notifications,null,null,ot)).json().priorityChanges.length,0);
   await priority(3,'priority-urgent');notices=(await call('GET',notifications,null,null,ot)).json();assert.equal(notices.priorityChanges.length,1);assert.equal(notices.priorityChanges[0].priority,3);assert.notEqual(notices.priorityChanges[0].event_id,n.event_id);
   jobs=(await call('GET',base+'/operator/work-orders',null,null,ot)).json().workOrders;assert.equal(jobs.find(j=>j.id===x.j).priority,3);
   assert.equal(notices.items.find(j=>j.work_order_id===x.j).queue_rank,2);
   await priority(0,'priority-lower');assert.equal((await call('GET',notifications,null,null,ot)).json().priorityChanges.length,0,'Lowering priority removes obsolete urgency');
   await admin.query(`UPDATE "${schema}".work_assignments SET released_at=now() WHERE work_order_id IN ($1,$2)`,[x.j,ahead.j]);
  });
