   const active=await call('GET',url+'?state=active',null,null,mt);assert.deepEqual(active.json().workOrders.map(x=>x.id),[a.j]);assert.equal(active.json().finishedCount,0);assert.deepEqual((await call('GET',url+'?state=finished',null,null,mt)).json().workOrders,[]);assert.equal((await call('GET',url+'?state=bad',null,null,mt)).statusCode,400);
